}

.box {
    position: relative;
    padding: 13px;
    width: 40%;
    z-index: 30;
}

.box.white {
    background-color: white;
}

.box.flat {
    box-shadow: 0px 1px 3px rgba(0, 0, 0, 0.16);
    border-radius: var(--boxes-radius);
}

.advanced-kpi {
    height: 100%;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
}

.advanced-kpi--top .title {
    font-size: 1.2em;
    margin: 0;
}

.advanced-kpi--top .description {
    margin: 0 auto;
    color: #565656;
    font-size: 1em;
    font-weight: 400;
}

.advanced-kpi--middle {
    display: flex;
    flex-direction: column;
    margin: 5px 0;
}

.advanced-kpi--middle.centered {
    align-items: center;
}

.advanced-kpi--middle > * {
    margin: 5px 0;
}

.advanced-kpi--middle .value {
    color: var(--highlight);
    font-weight: 500;
    font-size: 2rem;
}

.advanced-kpi--bottom {
    font-size: 0.8em;
}

/* Card
========================================================================== */

.card {
    color: #FFFFFF;
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    justify-content: flex-end;
    height: 100%;
    padding: 30px;
    border-radius: 4px;
    margin-bottom: 20px;
    background-color: #01abb0;
}

.card-title {
    color: inherit;
    text-align:center;
    font-size: 2.2rem;
    margin-top: 0;
    margin-bottom: 20px;
    line-height: 1.4;
    text-transform: uppercase;
    max-width: 100%;
}

.content-card {
    background-color: var(--boxes-background);
    padding: 26px;
    border-radius: 4px;
    margin-bottom: 20px;
    height: 100%;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
}

.content-card-icon {
    color: #fff;
    font-size: 2rem;
    margin-bottom: 13px;
    max-width: 100%;
}
.content-card-link {
    color: var(--links);
    font-weight: bold;
    transition: all .2s;
    opacity: 1;
    max-width: 100%;
}

.content-card-link:hover {
    opacity: .7;
    text-decoration: none;
}


/* KPI Card
   ========================================================================== */

.kpi-card {
	background-color: #01ABB0;
	height: 150px;
	padding: 19px;
	border-radius: 10px;
	margin-bottom: 20px;
	display: flex;
	flex-direction: column;
	align-items: center;
	text-align: center;
	justify-content: center;
	text-align: center;
}

.kpi-icon {
	color: var(--highlight);
	font-size: 4rem;
	margin-top: 0;
	margin-bottom: 13px;
	max-width: 90%;
}

.kpi-title {
	color: #fff;
	font-weight: normal;
	font-size: 1.8rem;
	margin-top: 0;
	margin-bottom: 13px;
	max-width: 100%;
}

.kpi-description {
	color: var(--text);

	font-size: 1rem;
	line-height: 1.5;
	font-weight: normal;
	margin-top: 0;
	margin-bottom: 0;
	max-width: 100%;
}

